    {"claim": "Bessen's data shows teller headcount actually grew through 2010, because cheaper branches meant banks opened more of them.", "targets": [], "relationship": ""},
    {"claim": "Redistribution hands you a pension for a role that's gone and calls it compassion. That's the colder choice.", "targets": [], "relationship": ""},
    {"claim": "Who actually bears the cost when the robot is a model API hosted in Dublin or Singapore?", "targets": [], "relationship": ""},
    {"claim": "Denmark's flexicurity model produces faster reemployment than rigid job-protection regimes, without freezing labor reallocation.", "targets": [], "relationship": ""},
    {"claim": "Show me the sector where net cognitive-labor demand has gone permanently to zero. Not reshuffled. Zero.", "targets": [], "relationship": ""}
  ]
}

